import React from 'react';

export default function EventCard({event,onClick}){
  return (
    <div className="card event-card" onClick={()=>onClick && onClick(event)} style={{cursor:'pointer'}}>
      <img src={event.image_url || 'https://via.placeholder.com/400x200'} alt={event.title} />
      <h3>{event.title}</h3>
      <p className="muted">{event.description && event.description.slice(0,120)}{event.description && event.description.length>120? '...': ''}</p>
    </div>
  );
}
